mapper.select:
SELECT PL.UNIT_PRICE       AS unitPrice
      ,PL.WAREHOUSING_DATE AS warehousingDate
      ,PL.DIVISION_CODE    AS divisionCode
      ,PL.VENDOR_CODE      AS vendorCode
FROM   PO_LEDGER PL
WHERE  PL.COMPANY_CODE = #{c.companyCode}
AND    PL.DIVISION_CODE = #{c.divisionCode}
AND    PL.ITEM_CODE = #{c.itemCode}
AND    PL.UNIT_PRICE > 0
AND    PL.WAREHOUSING_DATE BETWEEN #{fromYyyyMmdd} AND #{toYyyyMmdd}
ORDER  BY PL.WAREHOUSING_DATE DESC, PL.WAREHOUSING_NO DESC
FETCH FIRST 1 ROW ONLY

SELECT V.DIVISION_CODE AS reqDivisionCode ,V.ITEM_CODE AS reqItemCode ,PL.UNIT_PRICE AS unitPrice ,PL.WAREHOUSING_DATE AS warehousingDate ,PL.DIVISION_CODE AS divisionCode ,PL.VENDOR_CODE AS vendorCode FROM (
SELECT #{i.divisionCode} AS DIVISION_CODE, #{i.itemCode} AS ITEM_CODE
) V LEFT JOIN LATERAL (SELECT PL2.UNIT_PRICE ,PL2.WAREHOUSING_DATE ,PL2.DIVISION_CODE ,PL2.VENDOR_CODE FROM PO_LEDGER PL2 WHERE PL2.COMPANY_CODE = #{companyCode} AND PL2.DIVISION_CODE = V.DIVISION_CODE AND PL2.ITEM_CODE = V.ITEM_CODE AND PL2.UNIT_PRICE > 0 AND PL2.WAREHOUSING_DATE BETWEEN #{fromYyyyMmdd} AND #{toYyyyMmdd} ORDER BY PL2.WAREHOUSING_DATE DESC, PL2.WAREHOUSING_NO DESC FETCH FIRST 1 ROW ONLY) PL ON TRUE

SELECT SC.STANDARD_COST_AMOUNT AS standardCostAmount
      ,SC.APPLY_DATE          AS applyDate
      ,SC.DIVISION_CODE       AS divisionCode
FROM   STANDARD_COST SC
WHERE  SC.COMPANY_CODE = #{c.companyCode}
AND    SC.DIVISION_CODE = #{c.divisionCode}
AND    SC.ITEM_CODE = #{c.itemCode}
AND    #{c.resolvedBaseDate} BETWEEN SC.APPLY_DATE AND COALESCE(SC.END_DATE, '99991231')
ORDER  BY SC.APPLY_DATE DESC
FETCH FIRST 1 ROW ONLY

SELECT V.DIVISION_CODE AS reqDivisionCode ,V.ITEM_CODE AS reqItemCode ,SC.standardCostAmount AS standardCostAmount ,SC.applyDate AS applyDate ,SC.divisionCode AS divisionCode FROM (
SELECT #{i.divisionCode} AS DIVISION_CODE, #{i.itemCode} AS ITEM_CODE
) V LEFT JOIN LATERAL (SELECT SC2.STANDARD_COST_AMOUNT AS standardCostAmount ,SC2.APPLY_DATE AS applyDate ,SC2.DIVISION_CODE AS divisionCode FROM STANDARD_COST SC2 WHERE SC2.COMPANY_CODE = #{companyCode} AND SC2.DIVISION_CODE = V.DIVISION_CODE AND SC2.ITEM_CODE = V.ITEM_CODE AND #{baseDate} BETWEEN SC2.APPLY_DATE AND COALESCE(SC2.END_DATE, '99991231') ORDER BY SC2.APPLY_DATE DESC FETCH FIRST 1 ROW ONLY) SC ON TRUE
